class Solution {
    public int numTilePossibilities(String tiles){
        int[] count=new int[26];
        for(char ch:tiles.toCharArray())count[ch-'A']++;
        return dfs(count);
    }
    private int dfs(int[] count){
        int total=0;
        for(int i=0;i<26;i++)if(count[i]>0){
            count[i]--;
            total+=1+dfs(count);
            count[i]++;
        }
        return total;
    }
}

